import json
from pathlib import Path
B=Path(__file__).resolve().parents[1]
plans=json.loads((B/'tile_plans.json').read_text())
screens=json.loads((B/'screens.json').read_text())
gloss=json.loads((B/'inputs/path_glossary_bundle.json').read_text())
registry=json.loads((B/'scenario_asset_registry.json').read_text())
G={x['context']['concept_id']:x for x in gloss['bundles']}
# All excerpts below are authored, fictional inspect-and-judge evidence, not asset outputs.
checks={}
practices={}
def check(c,p,good,bad1,why1,bad2,why2,hint):
 checks.setdefault(c,[]).append((p,good,bad1,why1,bad2,why2,hint))
def practice(c,context,items,hint): practices[c]=(context,items,hint)
def ok(text,why): return (text,'supported',why)
def bad(text,why): return (text,'defective',why)
check('mle.pytorch_input_tensors','A conversion returned tensors, but features.shape is (4, 2) and targets.shape is (3,). What should an ordinary, non-optimized contract check do?', 'Reject the pair with a failed batch-alignment assertion before returning the tuple.', 'Return the tuple because construction succeeded.', 'Construction does not establish common batch length.', 'Cast targets to the feature dtype and accept the pair.', 'A dtype cast cannot repair missing corresponding observations.', 'Compare the observation axes before treating conversion as acceptance.')
practice('mle.pytorch_input_tensors','Review a conversion function for numerical order arrays. The declared feature dtype is torch.float32 and target dtype is torch.long. Supplied arrays preserve observation order. Accepted fixtures are (4, 2)/(4,) and the declared empty boundary (0, 2)/(0,); a three-target fixture and wrong-width fixture must fail. Judge each independent proposal against this contract.',[
 ok('import torch\ndef convert(features, targets, n, width):\n    f = torch.from_numpy(features).to(dtype=torch.float32)\n    t = torch.from_numpy(targets).to(dtype=torch.long)\n    assert f.shape == (n, width) and t.shape == (n,)\n    assert f.shape[0] == t.shape[0]\n    assert f.dtype == torch.float32 and t.dtype == torch.long\n    return f, t\n# Tests assert tuple shapes/dtypes for accepted and boundary fixtures,\n# verify supplied row identities, and expect AssertionError for three targets\n# and wrong feature width during ordinary non-optimized execution.', 'Separate declared dtypes, axes, common length and fixture correspondence are checked before returning the pair; both rejection fixtures are exercised.'),
 bad('f = torch.from_numpy(features).to(dtype=torch.float32)\nt = torch.from_numpy(targets).to(dtype=torch.float32)\nassert f.shape == (4, 2) and t.shape == (4,)\nreturn f, t', 'The target cast violates the separately declared long target representation even though the shapes match.'),
 bad('# Three-target trial\nf.shape = (4, 2); t.shape = (3,)\n# Conversion succeeded; skip assertions and return f, t.', 'Conversion success is not correspondence; the common observation length must be asserted and this trial rejected.')], 'Check representation and correspondence as separate requirements.')
check('mle.dataset_minibatch_loader','With shuffle=True, which claim about a properly implemented Dataset and DataLoader is justified?', 'Each returned feature remains paired with the target from the same source observation.', 'The first yielded item must be the first source observation.', 'Shuffling changes order; source-first position is not guaranteed.', 'Shuffling can legitimately pair a feature with a different observation’s target.', 'Order policy does not change the within-item correspondence contract.', 'Separate item identity from the order in which items arrive.')
practice('mle.dataset_minibatch_loader','Inspect loader evidence for five indexed numerical order observations and batch_size=2. Feature and target IDs must match. Judge the entire excerpt, including its assertions.',[
 ok('class Orders(Dataset):\n    def __len__(self): return 5\n    def __getitem__(self, index):\n        return features[index], targets[index]\n# shuffle=False: item-ID assertions match source order.\n# drop_last=False sizes: [2, 2, 1]; drop_last=True sizes: [2, 2].\n# shuffle=True: compare feature/target IDs within each item, not source positions.\n# Deliberately substituted wrong target ID fails an alignment assertion\n# with AssertionError in ordinary non-optimized execution.', 'Same-index retrieval, sample count, both partial-batch policies and shuffle-independent identity checks satisfy the declared evidence.'),
 bad('def __getitem__(self, index):\n    return features[index], targets[(index + 1) % 5]\n# Shapes and batch-size assertions all pass.', 'Well-shaped batches do not repair the shifted target index.'),
 bad('# DataLoader: batch_size=2, shuffle=False, drop_last=False\nassert observed_batch_sizes == [2, 2, 2]', 'The final incomplete batch is retained with one observation, not padded to two.')], 'Inspect how an item is formed before checking batch boundaries.')
check('mle.neural_model_definition','The declared contract is unconstrained outputs of shape (4, 1) for a (4, 2) input through widths 2 → 3 → 1. Which final arrangement satisfies it?', 'Linear(2, 3), ReLU(), Linear(3, 1), with no final activation.', 'Linear(2, 3), ReLU(), Linear(2, 1).', 'The intermediate output width is three, but the next layer expects two.', 'Linear(2, 3), ReLU(), Linear(3, 1), ReLU().', 'A final ReLU constrains outputs despite the stated unconstrained contract.', 'Trace the intermediate width, then check the final value contract.')
practice('mle.neural_model_definition','For four two-feature observations, review model definitions against widths 2 → 3 → 1, ReLU between linear layers and an unconstrained final output. A builder must return a registered nn.Module with an implemented forward method.',[
 ok('import torch.nn as nn\nclass OrderModel(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.layers = nn.Sequential(nn.Linear(2, 3), nn.ReLU(), nn.Linear(3, 1))\n    def forward(self, x):\n        return self.layers(x)\ndef build_model():\n    return OrderModel()\n# Fixture assertion: model(features).shape == (4, 1)', 'The subclass initializes its parent, registers its composition, implements forward and preserves the batch dimension with the required widths and final output.'),
 bad('self.layers = nn.Sequential(nn.Linear(2, 3), nn.ReLU(), nn.Linear(2, 1))\n# All other subclass and builder details are as required.', 'The second linear layer expects two inputs but receives three.'),
 bad('self.layers = nn.Sequential(nn.Linear(2, 3), nn.Linear(3, 1))\n# All other subclass and builder details are as required.', 'This omits the required intermediate nonlinearity.')], 'Trace both registration and the dimension chain.')
check('mle.autograd_gradients','Which assertion is appropriate after a fresh backward computation for Z=XW+b with supplied D already including loss reduction?', 'Compare W.grad with X.T @ D and b.grad with D summed over rows, checking shapes and explicit rtol/atol.', 'Divide both reference gradients by batch size again before comparing.', 'The supplied D already includes reduction, so another division changes the reference.', 'Check only that backward completed without an exception.', 'Successful execution does not verify matrix-shaped gradient agreement.', 'Keep the supplied reduction convention visible in the reference.')
X=[[1,2],[3,4]];D=[[.1],[.2]]
wg=[[round(sum(X[i][j]*D[i][0] for i in range(2)),10)] for j in range(2)]; bg=[round(sum(d[0] for d in D),10)]
practice('mle.autograd_gradients',f'Review gradient checks for X={X}, D={D} and Z=XW+b. D already includes the scalar-loss reduction. The supplied tolerance is rtol=1e-5, atol=1e-8. Valid and zero-D boundary references must pass; a deliberately perturbed reference must fail.',[
 ok(f'# Trainable leaf W and b have requires_grad=True.\nW.grad = None; b.grad = None\nloss = supplied_scalar_loss(X @ W + b)\nloss.backward()\nassert torch.allclose(W.grad, X.T @ D, rtol=1e-5, atol=1e-8)\nassert torch.allclose(b.grad, D.sum(dim=0), rtol=1e-5, atol=1e-8)\n# Observed gradient shapes: (2, 1), (1,); references: {wg}, {bg}.\n# Valid and zero-D cases pass. A perturbed reference raises AssertionError.', 'Fresh leaf gradients are compared with both correctly shaped references under explicit tolerances, including boundary and rejection checks.'),
 bad('# The same scalar loss is backpropagated twice without clearing W.grad or b.grad.\n# Compare the second accumulated gradients against the one-pass reference.', 'Backward accumulates gradients, so this is not a fresh single-pass comparison.'),
 bad('reference_W = (X.T @ D) / 2\nreference_b = D.sum(dim=0) / 2\n# Claim: the extra division is required by mean reduction.', 'D already carries the reduction; applying it again produces a different reference.')], 'Ask whether the gradient is fresh and whether reduction was applied exactly once.')
check('mle.task_loss_selection','For a three-class task with unnormalized logits of shape (N, 3), which target contract fits class-index CrossEntropyLoss?', 'Long targets of shape (N,) with indices in [0, 3).', 'Long targets of shape (N,) allowing index 3.', 'The upper bound is exclusive; index 3 is outside a three-class mapping.', 'Apply sigmoid first and use same-shaped binary targets for this class-index contract.', 'That substitutes the binary-logit target contract for the declared class-index one.', 'Check the output width against the target-index range.')
check('mle.task_loss_selection','Which input pair matches BCEWithLogitsLoss for the stated binary contract?', 'Raw logits and same-shaped targets in [0, 1].', 'Already-sigmoid probabilities and same-shaped targets in [0, 1].', 'BCEWithLogitsLoss combines sigmoid with binary cross-entropy and expects logits.', 'Raw logits and binary targets with a different shape.', 'The declared binary contract requires matching output and target shapes.', 'Distinguish the raw score from its sigmoid probability.')
out=[2,4];tar=[1,2];mse=sum((a-b)**2 for a,b in zip(out,tar))/len(out); deriv=[2*(a-b)/len(out) for a,b in zip(out,tar)]
practice('mle.task_loss_selection',f'Inspect mean-MSE proposals for outputs {out} and numerical targets {tar}. The function must verify equal shapes, choose mean MSE, check its loss and output derivatives, and interpret their signs.',[
 ok(f'assert outputs.shape == targets.shape\nloss = nn.MSELoss(reduction="mean")(outputs, targets)\nloss.backward()\n# Assert under supplied tolerances: loss.item() == {mse}; outputs.grad == {deriv}.\n# Each positive derivative means increasing that output farther above its\n# target increases loss.', 'Equal-shaped numerical targets, mean squared differences and the mean-reduced derivative reference agree; the sign interpretation is correct.'),
 bad('# Same fixture and equal-shape assertion\nloss = nn.MSELoss(reduction="sum")(outputs, targets)\n# Report this as the requested mean-reduced loss.', 'Sum reduction is not the declared mean loss or mean derivative contract.'),
 bad(f'# Correct measured derivatives: {deriv}\n# Report: increasing either output farther above its target decreases loss.', 'Positive derivatives indicate increasing loss in the direction of increasing output here, not decreasing loss.')], 'Write the mean factor before interpreting a derivative sign.')
check('mle.optimizer_configuration','A plain-SGD fixture uses a separate zero-learning-rate boundary case and an intentionally wrong expected-update reference. Which test policy is correct?', 'Assert unchanged parameters at zero learning rate; require the incorrect reference to fail an assertion.', 'Require a nonzero change even when learning rate is zero.', 'The plain-SGD change is minus learning rate times gradient, hence zero at that boundary.', 'Accept the incorrect reference whenever optimizer.step() runs.', 'Execution alone does not establish the declared update equation.', 'Distinguish a valid boundary from a false expected-update predicate.')
old=2;grad=3;lr=.1;new=round(old-lr*grad,10);delta=round(new-old,10)
practice('mle.optimizer_configuration','Inspect a baseline plain-SGD configuration: no momentum, weight decay or other modifications. The deterministic parameter is 2, its current gradient is 3 and learning rate is 0.1. Checks use supplied explicit tolerances.',[
 ok(f'optimizer = torch.optim.SGD(model.parameters(), lr=0.1)\noptimizer.zero_grad()\nloss.backward()\n# Snapshot parameter_before and current gradient before step.\noptimizer.step()\n# Assert parameter_after == {new} and change == {delta} within supplied tolerances.\n# Separate lr=0 boundary asserts parameter_after == 2.\n# Deliberately incorrect expected update raises AssertionError.', 'The optimizer is bound to model parameters and applies the current gradient in the right order; valid, zero-rate and false-reference tests distinguish the contract.'),
 bad('optimizer.zero_grad()\nloss.backward()\noptimizer.zero_grad()\noptimizer.step()\n# Expect the supplied nonzero current-gradient update.', 'Clearing after backward removes the gradient that the step is meant to apply.'),
 bad('optimizer = torch.optim.SGD(unrelated_parameters, lr=0.1)\n# unrelated_parameters are not any trainable model parameters.\n# Claim: this verifies the model parameter update.', 'The optimizer must receive the trainable model parameters, not a separate parameter collection.')], 'Follow parameter identity and the gradient’s lifetime through the update.')
check('mle.minibatch_training_loop','Which evidence verifies the declared loss-dependent plain-SGD change for each minibatch?', 'Retain before/after parameter values and the current gradient; assert their difference matches −learning_rate × current_gradient under tolerance.', 'Verify only that the epoch ended.', 'Finishing an epoch does not prove any current-gradient update occurred.', 'Compare every batch update with a gradient retained from the previous batch.', 'The update must be based on the intended current minibatch loss gradient.', 'Link each before/after pair to the gradient for that same minibatch.')
practice('mle.minibatch_training_loop','Review one declared epoch over five aligned observations in batches of two, retaining the final incomplete batch. Plain SGD must apply exactly one current-loss update per minibatch, with explicit tolerance checks.',[
 ok('for features, targets in loader:\n    predictions = model(features)\n    loss = loss_fn(predictions, targets)\n    optimizer.zero_grad()\n    loss.backward()\n    # Retain before parameter and current gradient.\n    optimizer.step()\n    # Assert after-before agrees with -learning_rate*current_gradient.\n    records.append((loss.item(), features.shape[0]))\n# Recorded counts: [2, 2, 1]; all three updates meet the equation and direction.\n# Valid and zero-rate boundary checks pass; a supplied false update\n# predicate raises AssertionError in ordinary non-optimized execution.', 'Each minibatch has a current-loss update, scalar diagnostic and actual count; the equation and boundary/rejection checks substantiate the updates.'),
 bad('for features, targets in loader:\n    loss = loss_fn(model(features), targets)\n    optimizer.zero_grad()\n    loss.backward()\n    optimizer.step()\n    optimizer.step()\n# Claim: exactly one update per current minibatch.', 'This applies two steps for one minibatch, violating the one-update contract.'),
 bad('# Valid single-step loop; record every batch count as configured batch_size.\n# Five observations, retained final batch: recorded counts [2, 2, 2].', 'Configured maximum is not the final batch’s actual count; the epoch evidence invents an observation.')], 'Audit the step count and the actual number of examples in each record.')
check('mle.training_evaluation_modes','For Dropout(p=0.5) in training mode, a random call retains every input element and scales each by two. Is this a valid boundary outcome?', 'Yes; every element obeys the zero-or-twice-input rule even if none is masked.', 'No; every training call must mask at least one element.', 'Random masking does not guarantee at least one zero on each call.', 'No; training dropout must be the identity just as evaluation dropout is.', 'Identity is the evaluation rule; retained training elements are scaled by 1/(1-p).', 'Apply the elementwise rule without requiring a particular random mask.')
practice('mle.training_evaluation_modes','Inspect a Dropout(p=0.5) fixture and the validation phase. Inputs are nonzero. Judge whether each report meets its stated mode, graph and assertion contract.',[
 ok('layer.eval()\nassert torch.equal(layer(x), x)\nlayer.train()\ntrain_output = layer(x)\nassert torch.all((train_output == 0) | (train_output == 2*x))\n# All-retained boundary output 2*x passes. Invalid output 3*x raises AssertionError.\nmodel.eval()\nwith torch.no_grad():\n    predictions = model(features)\n# Assert predictions have no recorded gradient graph; no optimizer step.\nmodel.train()\n# Final mode assertion passes.', 'The evaluation identity and probabilistic training rule are separate from graph control; validation is forward-only and training mode is restored.'),
 bad('model.train()\nwith torch.no_grad():\n    predictions = model(features)\n# Claim: no_grad switches dropout to evaluation behavior.', 'no_grad changes gradient recording, not the model’s layer mode.'),
 bad('model.eval()\nwith torch.no_grad():\n    predictions = model(features)\noptimizer.step()\nmodel.train()\n# Claim: this is forward-only validation.', 'An optimizer step violates forward-only validation even when prediction used eval and no_grad.')], 'Separate layer behavior, graph recording and parameter updates.')
check('mle.weight_persistence','What distinguishes a verified persistence check from merely successful loading?', 'Assert corresponding parameter entries and same-fixture evaluation predictions agree under explicit tolerances, and exercise boundary and failing predicates.', 'Treat any successful torch.load call as complete verification.', 'Loading without an exception does not verify parameter preservation or predictions.', 'Compare the restored model on a different fixture without matching the original inputs.', 'Prediction equivalence must use the same fixed fixture.', 'Ask which observable equivalence the checkpoint round trip is supposed to preserve.')
practice('mle.weight_persistence','Review a checkpoint round trip for the bounded order-training model. A compatible architecture, corresponding parameter state and fixed-input evaluation predictions must be preserved under supplied tolerances.',[
 ok('original.eval()\nreference = original(fixed_features)\nwith open(path, "wb") as handle:\n    torch.save(original.state_dict(), handle)\nrestored = build_same_architecture()\nwith open(path, "rb") as handle:\n    mapping = torch.load(handle, weights_only=True)\nrestored.load_state_dict(mapping)\nrestored.eval()\n# Assert corresponding state_dict entries match under supplied tolerances.\n# Assert restored(fixed_features) matches reference under those tolerances.\n# Valid and supplied boundary pass; deliberately false equality raises AssertionError.', 'Binary handles and weights-only loading restore the compatible state; matching entries and fixed-input evaluation predictions provide explicit acceptance evidence.'),
 bad('# Same checkpoint and fixed input.\nrestored = build_incompatible_architecture()\nrestored.load_state_dict(mapping)\n# Claim: a parameter mapping supplies the missing architecture contract.', 'The architecture must already be compatible before applying the saved parameter mapping.'),
 bad('# Compatible restored model; matching entries.\n# Original predictions use fixed_features; restored predictions use different_features.\n# Claim equivalence from comparing those outputs.', 'Different input fixtures do not establish the required fixed-input prediction equivalence.')], 'Check both the restored state and the conditions of the prediction comparison.')
check('mle.validation_early_stopping','The controller’s validation rule is predeclared. Which use of protected test observations stays within the training-decision boundary?', 'Keep them entirely outside preprocessing fitting, checkpoint selection and stopping decisions.', 'Use their loss to break a tie between candidate checkpoints.', 'A tie-break still chooses a model with protected test information.', 'Use them to choose patience while still monitoring validation loss.', 'Tuning patience with protected test observations leaks information into training decisions.', 'Consider whether protected information can change the chosen system.')
