practice('mle.validation_early_stopping',f'Inspect a minimized-validation-loss controller with min_delta=0.02, patience=2 and maximum_epochs=10. Losses at epochs 1–4 are {losses}. Only current < best − min_delta is an accepted improvement. Protected test data are unavailable to this controller.',[
 ok(f'# Bounded while loop: epoch < maximum_epochs.\n# Improvement branch resets counter and saves an independent checkpoint.\n# Otherwise increment counter; break when counter >= patience.\n# Observed counters: {counts}. Stop after epoch {len(counts)}.\n# Restore and report accepted epoch {best_epoch}, loss {best}.\n# Snapshot stored with a deep copy or file before later updates.\n# No protected-test access.', 'The strict improvement rule, consecutive counter, epoch bound and independent accepted snapshot determine the restored checkpoint.'),
 bad('# Correct accepted epoch identified.\nbest_state = model.state_dict()\n# Keep only this live mapping while later updates modify model parameters.\n# At stopping, load best_state and claim the accepted weights were preserved.', 'A live state_dict reference can change with later updates; preserve an independent snapshot.'),
 bad('# Select the lowest observed loss even if it fails min_delta.\n# Restore epoch 3 solely because its observed loss is lower than epoch 2.', 'The accepted checkpoint follows the declared minimum-improvement rule, not an unrestricted minimum over observed losses.')], 'Track accepted improvements rather than every numerical decrease.')
check('mle.training_failure_diagnosis','How should assertion fixtures distinguish a corrected valid run, a declared boundary and a reproduced failure?', 'Use explicit predicates for each expected outcome, with a deliberately false predicate raising AssertionError in ordinary execution.', 'Remove all assertions so the failure can finish.', 'Finishing without assertions does not establish acceptance or rejection of the expected outcomes.', 'Declare every run valid if any gradient exists.', 'A gradient’s existence alone does not verify declared loss, gradient and update expectations.', 'Make each acceptance claim an explicit predicate, not just a completed call.')
practice('mle.training_failure_diagnosis','Review a reproduced plain-SGD failure: output/target contract and mean loss match the fixed reference; post-backward gradients match the reference before clearing, but parameters do not change. The run log shows optimizer.zero_grad() after backward and before step. Keep the fixture and failing record fixed.',[
 ok('# Preserve failing fixture and reference.\n# Hypothesis: clearing after backward removes the intended update gradient.\n# Single correction: move zero_grad before backward; do not change loss or lr.\n# Rerun same bounded fixture; record loss, output derivatives, parameter.grad\n# after backward/before clearing, and before/after parameter values.\n# Loss/gradient references match; update matches -lr*current_gradient.\n# Valid and zero-lr boundary assertions pass; reproduced failure violates\n# the nonzero-update predicate; an intentionally false assertion raises AssertionError.', 'The evidence localizes the issue after gradient computation; one supported ordering correction is compared against unchanged loss, gradient and update references.'),
 bad('# Same recorded failure.\n# Change learning rate, loss function and gradient-clearing order together.\n# Rerun succeeds, so attribute the correction solely to learning rate.', 'Changing several factors cannot isolate the supported cause; the failure evidence specifically identifies gradient clearing before step.'),
 bad('loss.backward()\noptimizer.zero_grad()\n# Inspect parameter.grad only now and diagnose missing learning signal\n# as proof that backward never produced gradients.', 'Inspection after clearing cannot show whether backward produced the expected signal; inspect before clearing.')], 'Locate where the observed derivative chain stops matching the fixed reference.')
check('mle.device_placement','torch.cuda.is_available() reports False on the supplied supported CPU environment. What selection follows the availability rule?', 'Select torch.device("cpu") and record that actual choice.', 'Select CUDA because the requested workload would be faster there.', 'A desired speedup does not establish CUDA availability.', 'Select CUDA because the VM is described informally as GPU-capable.', 'Actual measured availability governs the device choice, not an informal label.', 'Use the measured availability, not the desired hardware.')
practice('mle.device_placement','Inspect a bounded workload on an already authorized supplied Compute Engine VM. INSTANCE and ZONE below refer only to that supplied VM. Judge compatible placement, valid/CPU-boundary/failure assertions and the complete lifecycle record.',[
 ok('describe INSTANCE --zone=ZONE: identity matches authorization; initial status TERMINATED\nstart INSTANCE --zone=ZONE: operation completed\ndescribe: same identity, RUNNING\nssh INSTANCE --zone=ZONE: connected\n# torch.cuda.is_available() determines device; actual choice recorded.\n# model.to(device), features.to(device), targets.to(device) once per needed input.\n# Parameter/input/target devices asserted equal; bounded forward/backward\n# and prediction complete. Supported CPU boundary passes.\n# Deliberate incompatible-device predicate raises AssertionError.\nstop INSTANCE --zone=ZONE: operation completed\ndescribe: same identity, TERMINATED\n# Commands above use gcloud compute instances, except gcloud compute ssh.', 'The authorized identity and lifecycle states are verified, actual availability guides compatible placement, and bounded execution plus assertion outcomes provide evidence.'),
 bad('# CUDA is available; model and features are on cuda, targets are on cpu.\n# A required computation consumes all three.\n# Claim that moving features alone establishes compatible placement.', 'Targets and model state also need compatible placement; moving features alone is insufficient.'),
 bad('# Correct compatible devices; bounded workload complete.\ngcloud compute instances stop INSTANCE --zone=ZONE\n# Do not wait or describe the resulting state; report shutdown verified.', 'Issuing stop is not verification; wait for completion and inspect the resulting authorized instance state.')], 'Inspect all participating tensors and both ends of the authorized lifecycle.')
check('mle.training_batch_sizing','A fast trial exceeds the supplied measured allocated-tensor memory bound; a slower completed trial meets all declared requirements. Which choice is eligible?', 'The completed trial that meets the memory and performance requirements.', 'The faster trial, because throughput overrides the bound.', 'Higher throughput does not excuse violating the declared memory bound.', 'The faster trial if its feature-plus-target byte estimate is below the bound.', 'Input estimates do not replace the measured training-memory quantity governed by this bound.', 'Apply eligibility requirements before ranking performance.')
