check('mle.training_bottleneck_profiling','Which final timing comparison supports a steady-state CUDA performance claim?', 'Warm up both runs, time the same workload without profiler overhead, and synchronize accelerator completion at both measurement boundaries.', 'Time only CPU submission of CUDA work without synchronization.', 'Asynchronous submission timing can omit accelerator completion.', 'Compare a cold profiled baseline with a warm unprofiled changed run.', 'Warm-up and profiler overhead differences confound the effect of the isolated change.', 'Match measurement conditions as carefully as workload conditions.')
practice('mle.training_bottleneck_profiling','Inspect evidence for the same bounded containerized order-training workload. Attribute the dominant stage from labeled profiler work with contemporaneous process evidence, then judge an isolated change using steady-state completion timings.',[
 ok('# Warm-up complete before profiling.\n# record_function("loading") encloses loading only;\n# record_function("compute") encloses model computation only.\n# Trace/key_averages attributes the largest limiting interval to loading.\n# Same-window docker stats and docker top corroborate loader process CPU pressure.\n# Reproduce loading limitation; change only the supported loading factor.\n# Matched unprofiled reruns: warm-up on both, same bounded work,\n# CUDA synchronization at start/end; completed elapsed time decreases.\n# Report loading as the supported bottleneck and the measured improvement.', 'Labeled attribution and same-window process evidence support loading; the one-factor final comparison removes warm-up, profiler and asynchronous-completion confounds.'),
 bad('# Profile labels show loading dominates; process evidence agrees.\n# Change loading and model architecture together.\n# Attribute any faster result solely to loading.', 'The diagnosis must be checked with one isolated supported change, not two simultaneous changes.'),
 bad('# CPU timer starts, submits CUDA work, then stops immediately.\n# No synchronize at either boundary.\n# Claim: the elapsed interval is completed accelerator computation.', 'CPU submission without completion boundaries does not measure completed asynchronous CUDA work.')], 'Use profiling for attribution and a matched unprofiled rerun for the performance comparison.')
check('mle.training_hardware_selection','Both authorized options finish benchmarking. Which record establishes the required shutdown and billing interpretation?', 'Verify both resulting stopped states; retain measured lifecycle durations and compute billing scope, acknowledging possible continuing disk charges.', 'Retain only bounded execution times and assume all charges stopped.', 'Execution time is not lifecycle-billed duration, and persistent disks or other charges may remain.', 'Stop the chosen option only, leaving the rejected benchmark VM running.', 'Both authorized benchmark options must be stopped and their resulting states verified.', 'A rejected option still has a lifecycle and billing record.')
practice('mle.training_hardware_selection','Review CPU/GPU capacity selection on two already authorized supplied VMs. Both must use the same bounded matrix workload, meet fixed completion/quality/memory/time/cost limits and finish in verified stopped states. Keep execution cost distinct from lifecycle-billed compute cost.',[
 ok('# For each authorized VM: describe identity/initial state; start and wait;\n# describe RUNNING; connect with gcloud compute ssh in supplied zone.\n# Same workload and quality criterion; record completion, observed memory,\n# warm-up interpretation and relevant movement in measured execution time.\n# Eligibility checks all fixed quality/memory/time/cost limits first.\n# Execution cost = execution_seconds * supplied per-second rate.\n# Lifecycle-billed compute cost = measured billable_lifecycle_seconds * rate.\n# Choose the eligible option under the declared decision rule.\n# Stop BOTH, wait, describe matching identities and TERMINATED states.\n# Retain lifecycle/billing evidence; disks or other charges may continue.', 'Matched eligibility, explicit cost scopes and both verified authorized lifecycles support the capacity decision.'),
 bad('# GPU execution is faster but its measured memory exceeds the fixed bound.\n# CPU completes and meets all fixed requirements.\n# Select GPU solely because execution is faster.', 'Speed does not make an over-bound option eligible.'),
 bad('# Both options completed. Use execution_seconds*rate as the full\n# lifecycle-billed compute cost, although measured running lifecycle\n# durations are longer; declare all disk charges ended after stop.', 'Billing uses the measured lifecycle scope, not just execution, and stopped compute does not establish that disk or other charges ended.')], 'Separate eligibility, execution performance and billed lifecycle scope.')
check('ml.task_specific_pretrained_weight_fine_tuning','What supports a justified improvement or non-improvement claim for the adapted two-class model?', 'Compare with the frozen pretrained reference on the same validation cohort using the fixed conditional-rate and expected-cost rules, excluding protected tests.', 'Use protected test errors to choose whether to retain the adapted model.', 'Using protected observations to choose a model leaks information into the selected system.', 'Claim improvement from changed head weights without a matched validation comparison.', 'Changed weights alone do not establish an improved result under the supplied acceptance and cost rules.', 'Separate evidence of learning from evidence of a better matched validation result.')
practice('ml.task_specific_pretrained_weight_fine_tuning','Inspect independent excerpts from a bounded two-class ViT supervised adaptation. Judge whether each excerpt supports its stated claim. Supplied training/validation images and scaffold are fixed; protected test observations must not enter adaptation or selection. No execution is requested.',[
 ok('# Compatible supplied checkpoint loaded; original label mapping retained\n# for frozen pretrained validation reference. Same checkpoint processor\n# used for training/validation pixel_values and model(**inputs).logits.\n# Freeze existing parameters, replace classifier with\n# nn.Linear(model.config.hidden_size, 2); set both num_labels fields and\n# matching id2label/label2id maps. TrainingArguments uses supplied epoch,\n# batch and learning-rate bounds, eval_strategy="epoch", remove_unused_columns=False.\n# Trainer receives supplied datasets/collator and processing_class=processor; train().\n# Post-run: head values changed; every frozen backbone value unchanged.', 'Compatible pretrained representation and mapping are retained; a new trainable two-class head receives the bounded supervised training while frozen backbone values remain unchanged.'),
 ok('# Adaptation-run logits shape (N, 2); targets shape (N,), torch.long,\n# all indices in [0, 2), matching the two-class maps.\n# Compute task loss; backward; before clearing, compare selected head\n# gradient with its supplied chain-rule reference under explicit tolerances.\n# Assertion passes with matching gradient shape and values.', 'The task label contract and selected head-gradient reference substantiate the intended supervised signal.'),
 ok('# Both models evaluated on the same fixed validation cohort.\n# FPR = FP/(FP+TN); FNR = FN/(FN+TP).\n# If either conditioning group is empty, report that rate as undefined\n# rather than substitute zero; do not claim a complete cost comparison\n# without the needed defined rates. Otherwise compute for BOTH models:\n# P(Y=0)*FPR*cost_FP + P(Y=1)*FNR*cost_FN, using supplied probabilities\n# and costs. Return both rates/costs and improvement or non-improvement\n# according to the fixed acceptance rule. No protected-test access.', 'The comparison conditions on the correct actual-class groups, applies the supplied expected-cost rule and handles undefined rates without leaking protected information.'),
 bad('# Head weights changed but frozen backbone values also changed.\n# Report successful classifier-only adaptation because a new head exists.', 'Classifier-only adaptation requires unchanged frozen backbone values as well as changed head weights.'),
 bad('# Same validation cohort, but compute FPR=FP/(FP+TP) and\n# substitute zero for FNR whenever there are no actual positives.\n# Use these numbers to claim lower expected cost.', 'FPR conditions on actual negatives, not predicted positives; an empty actual-positive group makes FNR undefined, not zero.')], 'Audit frozen state, label/gradient contracts and matched conditional-cost evidence separately.')

# Concrete recorded trials make the inspect-and-judge decisions applications,
# rather than classifications of generic procedure descriptions. Inputs are
# illustrative authored fixtures; every reported arithmetic result is computed.
trial_rows=[dict(size=2,peak=8000,seconds=5,complete=True),dict(size=4,peak=16000,seconds=3,complete=True),dict(size=8,peak=32000,seconds=2,complete=True)]
examples=5;memory_bound=20000;min_throughput=1
for r in trial_rows:
 r['counts']=[min(r['size'],examples-i) for i in range(0,examples,r['size'])]
 r['throughput']=examples/r['seconds']
 r['eligible']=r['complete'] and r['peak']<=memory_bound and r['throughput']>=min_throughput
chosen=max((r for r in trial_rows if r['eligible']),key=lambda r:r['throughput'])
trial_text='\n'.join(f"batch_size={r['size']}; actual counts={r['counts']}; completed={examples}; elapsed={r['seconds']} s; peak_allocated={r['peak']} bytes; completed/s={r['throughput']:.6f}; eligible={r['eligible']}" for r in trial_rows)
c='mle.training_batch_sizing'
context,items,hint=practices[c]
context+=f' Additional fixed trial limits: allocated-tensor peak <= {memory_bound} bytes and throughput >= {min_throughput} completed example/s. Each trial resets CUDA peak stats; alignment/task/other settings are unchanged. All five examples finish, including the last partial batch.'
items[0]=ok(f'# Recorded controlled comparison\n{trial_text}\n# Features have 20 four-byte columns; targets are four bytes each.\n# Report estimates from each actual batch row count separately from peaks.\n# Selection: batch_size={chosen["size"]}, highest throughput among eligible settings.\n# The larger, faster trial exceeds the allocated-tensor budget.', 'The actual partial-batch counts and completed-work rates support selecting the fastest eligible completed setting; the peak bound excludes the larger trial.')
practices[c]=(context,items,hint)
# A concrete allocation ledger and corrected peak record support attribution.
c='mle.training_memory_diagnosis';context,items,hint=practices[c]
ledger=dict(parameters=(20*10+10)*4,gradients=(20*10+10)*4,batch_features=100*20*4,batch_targets=100*4,activations=100*10*4,retained_graphs=20000)
live=sum(ledger.values()); corrected=live-ledger['retained_graphs'];memlimit=20000
context+=f' At the reproduced failure point, the supplied simultaneous-live ledger is {ledger} bytes; the allocator rejects a further required allocation under a {memlimit}-byte allocated-tensor bound. Failed allocated/reserved peaks and the point of failure are retained.'
items[0]=ok(f'# Sum the supplied simultaneous-live ledger: {live} bytes.\n# Parameter reference is (20*10+10)*4 = {ledger["parameters"]} bytes.\n# Failed peak allocated={live}; reserved={live+4000} bytes.\n# Graph-connected saved diagnostics require no future derivatives.\n# Single correction: store loss.item() instead of the graph-connected loss.\n# Same bounded task completes; corrected allocated peak={corrected},\n# corrected reserved peak={corrected+4000} bytes.\n# Retain both records; corrected allocated peak meets the {memlimit}-byte bound.', 'The ledger includes parameters, gradients, batch storage, activations and retained graphs at the same instant; removing only unnecessary diagnostic graph retention is supported by completion and the corrected allocated peak.')
practices[c]=(context,items,hint)
# Measured stage fractions and matched timings are computed from authored inputs.
c='mle.training_bottleneck_profiling';context,items,hint=practices[c]
stages=dict(loading=60,transfer=10,compute=20);before=100;after=80
items[0]=ok(f'# Warm-up complete; non-overlapping profiler labeled-region milliseconds:\n# {stages}. Loading region encloses only loading, compute only computation.\n# Loading share of attributed region time={stages["loading"]/sum(stages.values()):.6f}.\n# Same-window docker stats: loader process saturates its allotted CPU;\n# docker top confirms that process was running throughout the loading interval.\n# Reproduce the limitation; change only the supported loading factor.\n# Same bounded unprofiled CUDA work after warm-up on both runs, synchronized\n# at start/end: completed elapsed before={before} ms, after={after} ms.\n# Report loading as dominant; measured elapsed reduction={(before-after)/before:.6f}.', 'The loading-region attribution and contemporaneous loader CPU/process evidence agree. A one-factor matched unprofiled completion measurement supports the reported improvement.')
practices[c]=(context,items,hint)
# Concrete capacity choices: choose minimum lifecycle compute cost among eligible
# options, not minimum execution time. Costs are derived, never memorized.
c='mle.training_hardware_selection';context,items,hint=practices[c]
options=[dict(name='CPU',execution=60,lifecycle=100,rate=.01,memory=8000),dict(name='GPU',execution=20,lifecycle=40,rate=.04,memory=12000)]
limits=dict(memory=20000,execution_seconds=70,lifecycle_compute_cost=2)
for r in options:
 r['execution_cost']=round(r['execution']*r['rate'],10);r['lifecycle_cost']=round(r['lifecycle']*r['rate'],10)
 r['eligible']=r['memory']<=limits['memory'] and r['execution']<=limits['execution_seconds'] and r['lifecycle_cost']<=limits['lifecycle_compute_cost']
winner=min((r for r in options if r['eligible']),key=lambda r:r['lifecycle_cost'])
context+=f' The fixed limits are {limits}. Both complete the same quality-accepted workload. Select the eligible option with minimum lifecycle-billed compute cost under the supplied per-second rates; billable lifecycle durations are given below.'
records='\n'.join(f"# {r['name']}: execution={r['execution']} s, billable lifecycle={r['lifecycle']} s, rate={r['rate']} currency/s, observed memory={r['memory']} bytes, execution cost={r['execution_cost']}, lifecycle compute cost={r['lifecycle_cost']}, eligible={r['eligible']}" for r in options)
items[0]=ok(f'# Each supplied authorized identity/zone is confirmed by describe.\n# Both initially TERMINATED; start operations complete; describe RUNNING;\n# authorized gcloud compute ssh connects. Availability and compatible\n# model/input/target placement checked; matched task and quality criterion.\n# Warm-up and relevant movement included per fixed execution protocol.\n{records}\n# Choose {winner["name"]} by the declared lifecycle-cost rule.\n# Stop BOTH authorized VMs, wait for completion; describe confirms matching\n# identities in TERMINATED state. Retain lifecycle/cost records and continuing\n# disk/other charge scope separately.', 'Both options satisfy the fixed eligibility checks; the CPU has the lower lifecycle compute cost under the supplied durations and rates. Both authorized VM states are verified stopped without claiming all other charges ended.')
practices[c]=(context,items,hint)
# Actual conditional-rate/cost comparison plus an explicit undefined-group trap.
c='ml.task_specific_pretrained_weight_fine_tuning';context,items,hint=practices[c]
counts=dict(reference=dict(FP=2,TN=8,FN=3,TP=7),adapted=dict(FP=1,TN=9,FN=2,TP=8))
p0=.5;p1=.5;cfp=1;cfn=4
for r in counts.values():
 r['FPR']=r['FP']/(r['FP']+r['TN']);r['FNR']=r['FN']/(r['FN']+r['TP']);r['cost']=round(p0*r['FPR']*cfp+p1*r['FNR']*cfn,10)
context+=f' The comparison cohort has ten actual negatives and ten actual positives. Fixed deployment probabilities are P(Y=0)={p0}, P(Y=1)={p1}, error costs cost_FP={cfp}, cost_FN={cfn}, and correct predictions cost zero. The acceptance rule declares improvement only when all adaptation checks pass and expected error cost decreases.'
ct='\n'.join(f"# {name}: FP={r['FP']}, TN={r['TN']}, FN={r['FN']}, TP={r['TP']}; FPR={r['FPR']}, FNR={r['FNR']}, expected error cost={r['cost']}" for name,r in counts.items())
items[2]=ok(f'# Frozen pretrained and adapted predictions refer to exactly the same\n# validation observations, retained task mapping and checkpoint processor.\n{ct}\n# FPR denominator is actual negatives; FNR denominator is actual positives.\n# Both conditioning groups exist here. For supplied no-positive boundary,\n# FNR is explicitly undefined, not zero, and full cost is not claimed.\n# All head/backbone/shape/gradient checks passed as recorded. Expected error\n# cost decreases by {round(counts["reference"]["cost"]-counts["adapted"]["cost"],10)}; conclude improvement under the fixed rule.\n# Protected test observations never accessed.', 'Both models use matched validation evidence. The correctly conditioned rates and supplied deployment-cost calculation show a cost decrease; undefined boundary rates are explicitly handled rather than replaced with zero.')
practices[c]=(context,items,hint)

out={k:plans[k] for k in ['schema_version','path_id','batch_id']};out['kind']='interactions_part';out['tiles']=[]
seen=set(); check_index={}; remediation_index={}
for t,sc in zip(plans['tiles'],screens['tiles']):
 entries=[];tasks=[s for s in t['steps'] if s['type'] in ('check','hands_on')]
 for idx,s in enumerate(tasks):
  cid=s['concept_ids'][0]; bundle=G[cid]
  measures=[]
  for a in s['anchors']:
   if '#assessment:' in a:
    c,cap=a.split('#assessment:'); anchor=next(x for x in G[c]['assessment_anchors'] if x['capability']==cap)
    measures.append(dict(concept_id=c,capability=cap,fact_ids=anchor['fact_ids']))
  difficulty='intro' if idx==0 else ('stretch' if idx==len(tasks)-1 else 'core')
  ix=dict(type=s['planned_interaction_type'],interaction_id='ix.'+s['step_id'],difficulty=difficulty,grading_mode='client',standalone=True,measures=measures,anchors=s['anchors'])
  if s['type']=='check':
   ci=check_index.get(cid,0);check_index[cid]=ci+1
   p,good,b1,w1,b2,w2,hint=checks[cid][ci]
   # Rotate correct answer deterministically, so answer position is not a shortcut.
   opts=[(good,True,'This follows the stated contract.'),(b1,False,w1),(b2,False,w2)]
   shift=idx%len(opts);opts=opts[shift:]+opts[:shift]
   ix['public']=dict(prompt=p,options=[dict(option_id=f'o{i+1}',text=a[0]) for i,a in enumerate(opts)],selection='single',shuffle=True)
   ix['grading']=dict(correct_option_ids=[f'o{i+1}' for i,a in enumerate(opts) if a[1]],option_feedback={f'o{i+1}':dict(message=a[2]) for i,a in enumerate(opts)})
   correct='Correct. '+good;incorrect='Recheck the stated contract. '+w1+' '+w2
  else:
   context,items,hint=practices[cid]
   ix['public']=dict(prompt=context+' Sort every excerpt into Supported (all stated contract claims hold) or Defective (at least one stated claim violates the contract). Each excerpt is independent; comments describe recorded fixture evidence.',buckets=[dict(bucket_id='supported',label='Supported by the contract'),dict(bucket_id='defective',label='Defective claim or implementation')],items=[dict(item_id=f'e{i+1}',text=text) for i,(text,bucket,why) in enumerate(items)])
   ix['grading']=dict(assignments={f'e{i+1}':bucket for i,(text,bucket,why) in enumerate(items)},item_feedback={f'e{i+1}':dict(message=why) for i,(text,bucket,why) in enumerate(items)})
   correct='Correct. You distinguished the contract-satisfying evidence from the defective excerpts.';incorrect='Recheck each excerpt against its declared contract; successful execution or a plausible shape alone does not establish every acceptance claim.'
  ix['feedback']=dict(correct=dict(message=correct),incorrect=dict(message=incorrect),hints=[hint])
  rems=[r for r in sc.get('remediation_steps',[]) if cid in r['concept_ids']]
  ri=remediation_index.get(cid,0); remediation_index[cid]=ri+1
  if ri < len(rems): ix['feedback']['remediation_step_id']=rems[ri]['step_id']
  seen.add(cid)
  entries.append(dict(step_id=s['step_id'],interaction=ix))
 out['tiles'].append(dict(tile_id=t['tile_id'],interactions=entries))
